import 'dart:ui' show Locale;

/// Translates only known messages generated by the Word format adapters.
/// Authored document text and arbitrary provider errors are never translated.
class WordFormatStrings {
  WordFormatStrings(Locale locale)
    : _values = _translations[locale.languageCode] ?? english;

  final List<String> _values;

  String? translate(String input) {
    final message = input.startsWith('FormatException: ')
        ? input.substring('FormatException: '.length)
        : input;
    final index = english.indexOf(message);
    if (index >= 0) return _values[index];
    if (_malformed.contains(message)) return _values[10];
    return null;
  }

